# METADATA
# title: ÖPUL 2023 Naturschutz (18) – Vertragsabwicklung, Flächenänderungen, Ausstieg, Sanktionen
package oepul.o6_18.administration

import data.oepul.o6_18.lib

p := lib.params

y := lib.year

nat := lib.nat

current_area := sum([lib.area(parcel) | some parcel in lib.nat_parcels])

# O618-ADM-001: Toleranz für Flächenverringerung (5 %, max. 5 ha, jedenfalls 0,50 ha) auf Basis Vorjahresfläche.
previous_area := object.get(nat, "area_previous_year_ha", null)

tolerated_decrease_ha := lib.max2(lib.min2(p.area_decrease_tolerance.max_share * previous_area, p.area_decrease_tolerance.max_ha), p.area_decrease_tolerance.always_allowed_ha) if previous_area != null

# O618-ADM-002: Verlust der Verfügungsgewalt (Übertragung an andere Person) und zulässige Umwandlungen führen zu keiner Rückzahlung.
exempt_decrease_ha := object.get(nat, "area_lost_disposal_right_ha", 0) + object.get(nat, "area_permitted_conversion_ha", 0)

relevant_decrease_ha := lib.max2(0, (previous_area - current_area) - exempt_decrease_ha) if previous_area != null

repayment_area_ha := relevant_decrease_ha if {
	relevant_decrease_ha > tolerated_decrease_ha
}

repayment_area_ha := 0 if {
	relevant_decrease_ha <= tolerated_decrease_ha
}

findings contains f if {
	repayment_area_ha > 0
	f := {"rule_id": "O618-ADM-001", "message": sprintf("Flächenverringerung %.2f ha über Toleranz %.2f ha – Rückzahlung für gesamte Differenzfläche", [relevant_decrease_ha, tolerated_decrease_ha])}
}

# O618-ADM-003: Wechsel der bewirtschaftenden Person – Flächen sind weiterzuführen, Nachfolger tritt dem Vertrag bei.
findings contains f if {
	object.get(nat, "operator_change", false)
	f := {"rule_id": "O618-ADM-003", "message": "Bewirtschafterwechsel: Verpflichtung weiterführen, Nachfolger tritt Fördervertrag bei (solidarische Haftung)"}
}

exit := object.get(nat, "exit", {})

# O618-ADM-004: Ausstieg vor Ende des Vertragszeitraumes führt zur Rückforderung bereits gewährter Prämien.
repayment_of_granted_premiums if {
	object.get(exit, "exited", false)
	object.get(exit, "exit_year", 2029) <= 2028
	not repayment_waived
}

# O618-ADM-013/014: Keine Rückforderung bei gemeldeten dauerhaften Umständen, höherer Gewalt oder Ablehnung einer Vertragsanpassung (Revisionsklausel).
repayment_waived if object.get(exit, "revision_clause_refusal", false)

repayment_waived if {
	object.get(exit, "permanent_circumstance", false)
	object.get(exit, "reported_in_time", false)
}

repayment_waived if object.get(exit, "force_majeure_recognised", false)

premium_in_event_year if {
	object.get(exit, "permanent_circumstance", false)
	object.get(exit, "event_date", "9999-12-31") > sprintf("%d-04-15", [y])
}

premium_in_event_year if object.get(exit, "force_majeure_recognised", false)

# O618-ADM-005: Abmeldung im laufenden Jahr – Maßnahme im betroffenen Förderjahr nicht mehr gültig; Ausstieg bis zur Ankündigung einer VOK.
measure_valid_this_year if not deregistered_this_year

deregistered_this_year if object.get(exit, "exit_year", 0) == y

findings contains f if {
	object.get(exit, "exited", false)
	object.get(exit, "on_site_control_announced_before_exit", false)
	f := {"rule_id": "O618-ADM-005", "message": "Ausstieg nach Ankündigung/Durchführung einer Vor-Ort-Kontrolle nicht mehr möglich"}
}

# O618-ADM-006: Wiedereinstieg nach Ausstieg/Ausschluss/Nichtabgabe nur mit neuerlichem Maßnahmenantrag.
reentry_requires_new_application if object.get(exit, "exited", false)

reentry_requires_new_application if object.get(nat, "excluded", false)

reentry_requires_new_application if object.get(nat, "mfa_not_submitted_previous_year", false)

# O618-ADM-007: Maßnahmenwechsel NAT -> EBW bis spätestens 31.12.2025; Umwandlungen in NAT laut Tabelle.
switch := object.get(nat, "switch_to_ebw", {})

violations contains v if {
	object.get(switch, "requested", false)
	object.get(switch, "switch_date", "") > p.switch_to_ebw_until
	v := {"rule_id": "O618-ADM-007", "message": "Umstieg in Ergebnisorientierte Bewirtschaftung nur bis 31.12.2025"}
}

switch_into_nat_allowed(from_id, date) if {
	some row in data.o6_18.measure_switch_table.rows
	row.from_id == from_id
	"18" in row.to
	date <= row.until
}

# O618-ADM-008: Maßnahmenübernahme bis 15.04. (2023/2028: 17.04.), Ausweitung max. 50 %; Regionaler Naturschutzplan nur bei Betriebsauflösung/-teilung/-zusammenlegung.
takeover := object.get(nat, "takeover", {})

takeover_deadline := sprintf("%d-%v", [y, p.takeover.deadline_exception_years[sprintf("%d", [y])]])

takeover_deadline := sprintf("%d-%v", [y, p.takeover.deadline_month_day]) if {
	not p.takeover.deadline_exception_years[sprintf("%d", [y])]
}

violations contains v if {
	object.get(takeover, "requested", false)
	object.get(takeover, "date", "") > takeover_deadline
	v := {"rule_id": "O618-ADM-008", "message": sprintf("Maßnahmenübernahme nach Frist %v", [takeover_deadline])}
}

violations contains v if {
	object.get(takeover, "requested", false)
	taken := object.get(takeover, "taken_over_area_ha", 0)
	taken > 0
	object.get(takeover, "expansion_area_ha", 0) > p.takeover.max_expansion_share * taken
	v := {"rule_id": "O618-ADM-008", "message": "Maßnahmenübernahme führt zu Ausweitung auf andere Flächen um mehr als 50 %"}
}

violations contains v if {
	object.get(takeover, "includes_regional_plan", false)
	not object.get(takeover, "reason", null) in p.takeover.regional_plan_only_on
	v := {"rule_id": "O618-ADM-008", "message": "Übernahme des Zuschlags Regionaler Naturschutzplan nur bei Betriebsauflösung, -teilung oder -zusammenlegung"}
}

# O618-ADM-009: Sanktionsstufen; ab 2027 Einbehalt 1 % statt Verwarnung; Ausschluss bei zweimaliger 100 %-Kürzung.
sanction_share(level) := row.reduction_share if {
	some row in p.sanction_levels
	row.level == level
	object.get(row, "from_year", 0) <= y
	y <= object.get(row, "until_year", 9999)
}

sanction_share("warning") := 0.01 if y >= 2027

excluded if object.get(nat, "hundred_percent_reductions_in_contract_period", 0) >= 2

findings contains f if {
	excluded
	f := {"rule_id": "O618-ADM-009", "message": "Ausschluss aus der Maßnahme und Rückforderung der im Vertragszeitraum gewährten Prämien (zweimalige 100 %-Kürzung)"}
}

# O618-ADM-010: Nichterfüllung von Zugangsvoraussetzungen: im 1. Jahr kein Vertrag; ab 2. Jahr keine Prämie im betroffenen Jahr.
access_failure_consequence := "no_contract" if {
	object.get(nat, "access_requirements_failed", false)
	y == nat.contract_start_year
}

access_failure_consequence := "no_premium_this_year" if {
	object.get(nat, "access_requirements_failed", false)
	y > nat.contract_start_year
}

# O618-ADM-011: Verweigerung der Vor-Ort-Kontrolle – Antrag abgelehnt, Verträge beendet und rückabgewickelt.
findings contains f if {
	object.get(nat, "refused_on_site_control", false)
	not object.get(nat, "refusal_force_majeure", false)
	f := {"rule_id": "O618-ADM-011", "message": "Kontrollverweigerung: keine Prämie im laufenden Jahr, Verträge beendet und rückabgewickelt"}
}

# O618-ADM-012: Nicht beantragte Folgejahre – Verpflichtung bleibt, keine Zahlung; nach > 1 Jahr endet sie mit Rückzahlung.
missed := object.get(nat, "payment_claim_missed_since_year", null)

payment_claim_consequence := "obligation_remains_no_payment" if {
	missed != null
	y - missed < p.late_payment_claim_limit_years
}

payment_claim_consequence := "obligation_ends_full_repayment" if {
	missed != null
	y - missed >= p.late_payment_claim_limit_years
}

# O618-ADM-015: Nichterfüllung durch reines Fremdverschulden: maßnahmenbezogener OP-Code, keine Prämie am Schlag; sonst Code löschen oder Selbstanzeige.
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(parcel, ["naturschutz", "noncompliance", "occurred"], false)
	object.get(parcel, ["naturschutz", "noncompliance", "third_party_fault"], false)
	not lib.has_code(parcel, "OPNAT")
	not lib.has_code(parcel, "OP")
	v := {"rule_id": "O618-ADM-015", "message": sprintf("Schlag %v: Fremdverschulden – maßnahmenbezogenen OP-Code vergeben", [parcel.parcel_id])}
}

violations contains v if {
	some parcel in lib.nat_parcels
	object.get(parcel, ["naturschutz", "noncompliance", "occurred"], false)
	not object.get(parcel, ["naturschutz", "noncompliance", "third_party_fault"], false)
	not object.get(parcel, ["naturschutz", "noncompliance", "self_reported"], false)
	v := {"rule_id": "O618-ADM-015", "message": sprintf("Schlag %v: Verstoß ohne Fremdverschulden – NAT-Code löschen oder Selbstanzeige", [parcel.parcel_id])}
}

# O618-ADM-017: Unterjährige Weitergabe nur prämienfähig, wenn Nachfolger die Auflagen bis Jahresende weiterführt (sonst OP-Code).
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(parcel, ["oepul", "transferred_during_year"], false)
	not object.get(parcel, ["oepul", "successor_continues_until_year_end"], false)
	not lib.has_code(parcel, "OP")
	not lib.has_code(parcel, "OPNAT")
	v := {"rule_id": "O618-ADM-017", "message": sprintf("Schlag %v: unterjährige Weitergabe ohne Weiterführung – OP-Code erforderlich", [parcel.parcel_id])}
}

# O618-ADM-018: Unmögliche Maßnahmenkombinationen bis zur Auszahlungsmitteilung korrigierbar (ohne VOK-Beanstandung).
combination_correction_possible if {
	not object.get(nat, "payment_notice_received", false)
	not object.get(nat, "on_site_control_objection", false)
}

# O618-ADM-021: Versuchsflächen (Code VF) – schriftliche Genehmigung, Dokumentation, keine Prämie im laufenden Jahr.
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_code(parcel, "VF")
	not object.get(parcel, ["oepul", "trial_written_approval"], false)
	v := {"rule_id": "O618-ADM-021", "message": sprintf("Schlag %v: Versuchsfläche ohne schriftliche Genehmigung", [parcel.parcel_id])}
}

# METADATA
# title: ÖPUL 2023 Naturschutz (18) – Kombinationen (Anhang J, Anhang L, UBB/BIO, EBW)
package oepul.o6_18.combinations

import data.oepul.o6_18.lib

p := lib.params

matrix_row(ch) := row if {
	some row in data.o6_18.annex_j.matrix
	row.chapter == ch
}

chapter_codes(parcel) := {c | some c in lib.auflagen_of(parcel); lib.chapter_of(c)}

# O618-KOMB-001: Kapitel S, A (inkl. T), B, G, W, O untereinander nicht kombinierbar; L/H laut Matrix Anhang J.
violations contains v if {
	some parcel in lib.nat_parcels
	some c1 in chapter_codes(parcel)
	some c2 in chapter_codes(parcel)
	ch1 := lib.chapter_of(c1)
	ch2 := lib.chapter_of(c2)
	ch1 < ch2
	matrix_row(ch1)[ch2] == false
	v := {"rule_id": "O618-KOMB-001", "parcel_id": parcel.parcel_id, "message": sprintf("Auflagen %v (Kapitel %v) und %v (Kapitel %v) laut Anhang J nicht kombinierbar", [c1, ch1, c2, ch2])}
}

# O618-KOMB-002: Verpflichtende Kombinationen (SB/SC nur mit SA01; GF nur mit GE01-GE03; BD nur mit BC01).
required_any(c) := r if {
	a := lib.auflage_by_code[c]
	c == a.code
	r := a.requires_any_of
	r != null
}

required_any(c) := r if {
	a := lib.auflage_by_code[c]
	c != a.code
	r := a.alias_requires_any_of[c]
}

required_any(c) := ["SA01"] if {
	startswith(c, "SC")
	not lib.auflage_by_code[c].requires_any_of
}

violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	req := required_any(c)
	not lib.has_any_auflage(parcel, req)
	v := {"rule_id": "O618-KOMB-002", "parcel_id": parcel.parcel_id, "message": sprintf("Auflage %v verpflichtend mit einer von %v zu kombinieren", [c, req])}
}

# O618-KOMB-003: AC01 und AC03 sind mit AA06 nicht kombinierbar.
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	excl := lib.auflage_by_code[c].not_combinable_with
	excl != null
	some x in excl
	lib.has_auflage(parcel, x)
	c < x
	v := {"rule_id": "O618-KOMB-003", "parcel_id": parcel.parcel_id, "message": sprintf("Auflagen %v und %v nicht kombinierbar", [c, x])}
}

# O618-KOMB-004/005: GL06/GL15/GL25 bzw. TA/TB verlangen UBB oder BIO samt Monitoring-Zuschlag.
violations contains v if {
	some req in p.monitoring_requirements
	some parcel in lib.nat_parcels
	some c in req.auflage_codes
	lib.has_auflage(parcel, c)
	not monitoring_fulfilled(req)
	rid := monitoring_rule_id(req.option)
	v := {"rule_id": rid, "parcel_id": parcel.parcel_id, "message": sprintf("Auflage %v erfordert Teilnahme an UBB oder BIO mit Zuschlag Monitoring '%v'", [c, req.option])}
}

monitoring_fulfilled(req) if {
	lib.participates_ubb_or_bio
	req.option in lib.monitoring_options
}

monitoring_rule_id("schnittzeit_phaenologie") := "O618-KOMB-004"

monitoring_rule_id("grosstrappe") := "O618-KOMB-005"

# O618-KOMB-017: Monitoring-Zuschläge (UBB/BIO) nur mit NAT-Teilnahme und passender Auflage auf mind. einem Schlag.
violations contains v if {
	"grosstrappe" in lib.monitoring_options
	not any_nat_auflage(["TA01"])
	v := {"rule_id": "O618-KOMB-017", "parcel_id": null, "message": "Monitoring Großtrappe nur bei Naturschutz-Teilnahme mit Auflage TA01 auf mind. einem Schlag"}
}

violations contains v if {
	"schnittzeit_phaenologie" in lib.monitoring_options
	not any_nat_auflage(["GL06", "GL15", "GL25"])
	v := {"rule_id": "O618-KOMB-017", "parcel_id": null, "message": "Monitoring Schnittzeit nach Phänologie nur bei Naturschutz-Teilnahme mit GL06/GL15/GL25 auf mind. einem Schlag"}
}

any_nat_auflage(cs) if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, cs)
}

# O618-KOMB-006: Anrechnung NAT-Ackerstilllegung als Biodiversitätsfläche (SA01 inkl. SB01-SB18/SC02, Grünbrache, NAT + DIV).
div_countable_arable contains parcel.parcel_id if {
	lib.participates_ubb_or_bio
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, p.div_accounting.arable.auflage_codes_any_of)
	object.get(parcel, ["oepul", "schlagnutzung"], null) in p.div_accounting.arable.schlagnutzung
	every c in p.div_accounting.arable.required_codes {
		lib.has_code(parcel, c)
	}
}

# O618-KOMB-007: Anrechnung NAT-Grünland mit Schnittzeitpunktverzögerung als Biodiversitätsfläche (NAT + DIVSZ).
div_countable_grassland contains parcel.parcel_id if {
	lib.participates_ubb_or_bio
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, p.div_accounting.grassland.auflage_codes_any_of)
	object.get(parcel, ["oepul", "schlagnutzung"], null) in p.div_accounting.grassland.schlagnutzung
	every c in p.div_accounting.grassland.required_codes {
		lib.has_code(parcel, c)
	}
}

div_countable := div_countable_arable | div_countable_grassland

# O618-KOMB-008: NAT-Schläge mit DIV/DIVSZ, die die Anrechnungsbedingungen nicht erfüllen.
violations contains v if {
	some parcel in lib.nat_parcels
	some dc in ["DIV", "DIVSZ"]
	lib.has_code(parcel, dc)
	not parcel.parcel_id in div_countable
	v := {"rule_id": "O618-KOMB-008", "parcel_id": parcel.parcel_id, "message": sprintf("NAT-Schlag mit Code %v erfüllt die Anrechnungsbedingungen als Biodiversitätsfläche nicht", [dc])}
}

# O618-KOMB-009: Feldstücke > 5 ha: mind. 0,15 ha Biodiversitätsfläche auch bei Einbringung in NAT (bei UBB/BIO).
feldstuecke contains fs if {
	some parcel in lib.parcels
	fs := object.get(parcel, ["oepul", "feldstueck_id"], null)
	fs != null
}

feldstueck_area(fs) := max([object.get(parcel, ["oepul", "feldstueck_area_ha"], 0) |
	some parcel in lib.parcels
	object.get(parcel, ["oepul", "feldstueck_id"], null) == fs
])

feldstueck_div_area(fs) := sum([lib.area(parcel) |
	some parcel in lib.parcels
	object.get(parcel, ["oepul", "feldstueck_id"], null) == fs
	counts_as_div(parcel)
])

counts_as_div(parcel) if parcel.parcel_id in div_countable

counts_as_div(parcel) if {
	not lib.is_nat(parcel)
	some dc in ["DIV", "DIVSZ", "DIVNFZ", "DIVAGF", "DIVRS"]
	lib.has_code(parcel, dc)
}

feldstueck_has_nat(fs) if {
	some parcel in lib.nat_parcels
	object.get(parcel, ["oepul", "feldstueck_id"], null) == fs
}

violations contains v if {
	lib.participates_ubb_or_bio
	some fs in feldstuecke
	feldstueck_has_nat(fs)
	feldstueck_area(fs) > p.div_accounting.feldstueck_threshold_ha
	feldstueck_div_area(fs) < p.div_accounting.feldstueck_min_div_area_ha
	v := {"rule_id": "O618-KOMB-009", "parcel_id": null, "message": sprintf("Feldstück %v > 5 ha ohne mind. 0,15 ha Biodiversitätsfläche", [fs])}
}

# O618-KOMB-010: Keine Prämienkombination auf der Einzelfläche außer Natura 2000 (23) und Landschaftselement-Abgeltung (1A/1B).
allowed_single_area := {m | some row in data.o6_18.annex_l_row_18.combinations; m := row.measure_id}

conflicting_single_area_measures(parcel) := {m |
	some m in object.get(parcel, ["oepul", "other_area_measures"], [])
	not m in allowed_single_area
}

violations contains v if {
	some parcel in lib.nat_parcels
	bad := conflicting_single_area_measures(parcel)
	count(bad) > 0
	v := {"rule_id": "O618-KOMB-010", "parcel_id": parcel.parcel_id, "message": sprintf("NAT-Fläche prämienmäßig nicht kombinierbar mit %v", [bad])}
}

# 1A/1B auf NAT-Einzelfläche nur hinsichtlich Abgeltung der Landschaftselemente (Fußnote 1).
violations contains v if {
	some parcel in lib.nat_parcels
	some m in object.get(parcel, ["oepul", "other_area_measures"], [])
	m in {"1A", "1B"}
	not object.get(parcel, ["oepul", "ubb_bio_only_landscape_elements"], false)
	v := {"rule_id": "O618-KOMB-010", "parcel_id": parcel.parcel_id, "message": sprintf("Maßnahme %v auf NAT-Fläche nur betreffend Abgeltung der Landschaftselemente kombinierbar", [m])}
}

# O618-KOMB-012: NAT ist mit EBW am Betrieb kombinierbar (keine Einzelflächen-Doppelförderung).
farm_level_combinable(m) if m in p.farm_level_combinable_measures

violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_code(parcel, "EBW")
	v := {"rule_id": "O618-KOMB-012", "parcel_id": parcel.parcel_id, "message": "Schlag gleichzeitig mit NAT und EBW codiert – Kombination nur auf Betriebsebene"}
}

# O618-KOMB-014: NPF-Code (bis 2024) – Anrechnung für GLÖZ 8, keine ÖPUL-Prämie.
npf_parcels contains parcel.parcel_id if {
	some parcel in lib.nat_parcels
	lib.has_code(parcel, "NPF")
	lib.year <= p.npf_code_until_year
}

violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_code(parcel, "NPF")
	lib.year > p.npf_code_until_year
	v := {"rule_id": "O618-KOMB-014", "parcel_id": parcel.parcel_id, "message": "Code NPF ist ab dem Antragsjahr 2025 nicht mehr zulässig"}
}

# O618-KOMB-015: K20-Flächen auf der Einzelfläche mit keinen anderen Maßnahmen kombinierbar.
k20_parcel(parcel) if {
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].chapter == "K"
}

k20_parcel(parcel) if lib.has_code(parcel, "K20")

violations contains v if {
	some parcel in lib.nat_parcels
	k20_parcel(parcel)
	count(object.get(parcel, ["oepul", "other_area_measures"], [])) > 0
	v := {"rule_id": "O618-KOMB-015", "parcel_id": parcel.parcel_id, "message": "K20-Fläche auf der Einzelfläche mit keiner anderen Maßnahme kombinierbar"}
}

# O618-KOMB-016: Als DIV angerechnete NAT-Flächen erhalten die NAT-Prämie (keine UBB-Prämie) und zählen nicht für den >7 %-Zuschlag.
div_counted_receive_nat_premium_only := div_countable

# METADATA
# title: ÖPUL 2023 Naturschutz (18) – Teilnahme- und Zugangsvoraussetzungen
package oepul.o6_18.eligibility

import data.oepul.o6_18.lib

p := lib.params

# O618-ELIG-001: Projektbestätigung der für Naturschutz zuständigen Landesstelle ist Voraussetzung.
violations contains v if {
	some parcel in lib.nat_parcels
	not object.get(lib.pc(parcel), "present", false)
	v := {"rule_id": "O618-ELIG-001", "parcel_id": parcel.parcel_id, "message": "NAT-Schlag ohne Projektbestätigung der für Naturschutz zuständigen Stelle des Landes"}
}

# O618-ELIG-002: Mindestens ein Schlag je Teilnahmejahr nach den Vorgaben der Maßnahme.
violations contains v if {
	lib.participates("18")
	count(lib.nat_parcels) < p.min_participating_plots_per_year
	v := {"rule_id": "O618-ELIG-002", "parcel_id": null, "message": "Kein Schlag mit Code NAT im Teilnahmejahr beantragt"}
}

# O618-ELIG-003: Förderung nur für Acker- und Grünlandflächen (ohne Almen).
violations contains v if {
	some parcel in lib.nat_parcels
	not parcel.land_use in p.eligible_land_uses
	v := {"rule_id": "O618-ELIG-003", "parcel_id": parcel.parcel_id, "message": sprintf("Nutzungsart %v ist in Naturschutz nicht förderfähig (nur Acker/Grünland ohne Alm)", [parcel.land_use])}
}

# O618-ELIG-004: Maßnahmenantrag bis spätestens 31.12. vor Vertragsbeginn.
application_deadline := sprintf("%d-12-31", [lib.nat.contract_start_year - 1])

violations contains v if {
	app := object.get(lib.nat, "application_date", null)
	app != null
	app > application_deadline
	v := {"rule_id": "O618-ELIG-004", "parcel_id": null, "message": sprintf("Maßnahmenantrag %v nach Frist %v", [app, application_deadline])}
}

# O618-ELIG-005: Letzter Einstieg mit Förderjahr 2025 (Beantragung bis 31.12.2024).
violations contains v if {
	start := object.get(lib.nat, "contract_start_year", null)
	start != null
	start > p.contract.last_entry_year
	v := {"rule_id": "O618-ELIG-005", "parcel_id": null, "message": sprintf("Vertragsbeginn %d nach letztem Einstiegsjahr %d", [start, p.contract.last_entry_year])}
}

violations contains v if {
	start := object.get(lib.nat, "contract_start_year", null)
	start != null
	start < 2023
	v := {"rule_id": "O618-ELIG-005", "parcel_id": null, "message": "Vertragsbeginn vor ÖPUL 2023 nicht möglich"}
}

# O618-ELIG-006: Vertragszeitraum bis 31.12.2028; Dauer je Beginnjahr 6/5/4 Jahre.
contract_duration_years := opt.duration_years if {
	some opt in p.contract.start_options
	opt.start_year == lib.nat.contract_start_year
}

contract_end_date := p.contract.end_date

in_contract_period if {
	lib.nat.contract_start_year <= lib.year
	lib.year <= 2028
}

# O618-ELIG-007: Beantragung eines Schlages über Code NAT in der Feldstücksliste.
violations contains v if {
	some parcel in lib.parcels
	count(lib.auflagen_of(parcel)) > 0
	object.get(parcel, ["naturschutz", "applied_for_measure"], false)
	not lib.is_nat(parcel)
	v := {"rule_id": "O618-ELIG-007", "parcel_id": parcel.parcel_id, "message": "Schlag für Naturschutz vorgesehen, aber nicht mit Code NAT gekennzeichnet"}
}

# O618-ELIG-008: Für die Auszahlung muss eine Naturschutz-Referenzfläche vorhanden sein.
no_payment_parcels contains parcel.parcel_id if {
	some parcel in lib.nat_parcels
	not object.get(lib.ns(parcel), "reference_area_present", false)
}

# O618-ELIG-009: Regionaler Naturschutzplan – jährliche Teilnahmebestätigung zusätzlich zur Projektbestätigung.
regional_plan := object.get(lib.nat, "regional_plan", {})

regional_plan_eligible if {
	object.get(regional_plan, "applied", false)
	object.get(regional_plan, "participation_confirmation", false)
	some parcel in lib.nat_parcels
	object.get(lib.pc(parcel), "present", false)
}

violations contains v if {
	object.get(regional_plan, "applied", false)
	not object.get(regional_plan, "participation_confirmation", false)
	v := {"rule_id": "O618-ELIG-009", "parcel_id": null, "message": "Zuschlag Regionaler Naturschutzplan ohne jährliche Teilnahmebestätigung"}
}

# O618-ELIG-010: Zuschlag Regionaler Naturschutzplan vor Vertragsbeginn bis 31.12. beantragen; letzter Einstieg 2028 (Antrag bis 31.12.2027).
violations contains v if {
	app := object.get(regional_plan, "application_date", null)
	app != null
	app > p.regional_plan.last_application_date
	v := {"rule_id": "O618-ELIG-010", "parcel_id": null, "message": sprintf("Antrag Regionaler Naturschutzplan %v nach letzter Frist %v", [app, p.regional_plan.last_application_date])}
}

violations contains v if {
	app := object.get(regional_plan, "application_date", null)
	app != null
	app > sprintf("%d-12-31", [lib.year - 1])
	v := {"rule_id": "O618-ELIG-010", "parcel_id": null, "message": "Zuschlag Regionaler Naturschutzplan nicht bis 31.12. vor dem Förderjahr beantragt"}
}

# O618-ELIG-011: Automatische Verlängerung des Zuschlags, wenn nicht abgemeldet und Teilnahmebestätigung vorliegt.
regional_plan_renews_next_year if {
	object.get(regional_plan, "applied", false)
	not object.get(regional_plan, "deregistered", false)
	object.get(regional_plan, "participation_confirmation", false)
	lib.year < 2028
}

# O618-ELIG-012: Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr (0,50 ha geschützter Anbau oder 1,50 ha).
violations contains v if {
	object.get(input, ["farm", "oepul", "first_oepul_year"], null) == lib.year
	object.get(input, ["farm", "oepul", "protected_cultivation_area_ha"], 0) < p.min_farm_size_first_year.protected_cultivation_ha
	object.get(input, ["land", "total_area_ha"], 0) < p.min_farm_size_first_year.total_area_ha
	v := {"rule_id": "O618-ELIG-012", "parcel_id": null, "message": "Betriebsmindestgröße im ersten ÖPUL-Jahr nicht erreicht"}
}

# O618-ELIG-013: Förderwerbende Personen; Gebietskörperschaften bzw. Beteiligung > 25 % ausgeschlossen.
applicant := object.get(input, ["farm", "oepul", "applicant"], {})

violations contains v if {
	t := object.get(applicant, "type", null)
	t != null
	not t in p.applicant.eligible_types
	v := {"rule_id": "O618-ELIG-013", "parcel_id": null, "message": sprintf("Förderwerbende Person vom Typ %v für Naturschutz nicht zulässig", [t])}
}

violations contains v if {
	object.get(applicant, "public_share_percent", 0) > p.applicant.max_public_share_percent
	v := {"rule_id": "O618-ELIG-013", "parcel_id": null, "message": "Beteiligung von Gebietskörperschaften über 25 %"}
}

# O618-ELIG-014: Auflagen müssen in Anhang I definiert und im Antragsjahr gültig sein.
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	not lib.auflage_by_code[c]
	v := {"rule_id": "O618-ELIG-014", "parcel_id": parcel.parcel_id, "message": sprintf("Auflage %v ist nicht in Anhang I definiert", [c])}
}

violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c]
	not lib.valid_in_year(c, lib.year)
	v := {"rule_id": "O618-ELIG-014", "parcel_id": parcel.parcel_id, "message": sprintf("Auflage %v ist im Antragsjahr %d nicht gültig", [c, lib.year])}
}

# O618-ELIG-015: GG-Auflagen (lange Wegzeit) nur für Bergmähder und begründete Ausnahmefälle.
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].bergmahd_or_justified_exception_only
	not object.get(lib.ns(parcel), "is_bergmahd", false)
	not object.get(lib.ns(parcel), "gg_exception_justified", false)
	v := {"rule_id": "O618-ELIG-015", "parcel_id": parcel.parcel_id, "message": sprintf("Auflage %v nur für Bergmähder oder begründete Ausnahmefälle", [c])}
}

# O618-ELIG-016: HG01/HG02 nur auf gemeldeten und im AMA-GIS eingezeichneten Flächen.
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].habitat_layer_required
	not object.get(lib.ns(parcel), "habitat_layer_registered", false)
	v := {"rule_id": "O618-ELIG-016", "parcel_id": parcel.parcel_id, "message": sprintf("Auflage %v nur auf von Landesdienststellen gemeldeten, im GIS eingezeichneten Flächen", [c])}
}

# O618-ELIG-017: Flächengrößenbedingungen einzelner Auflagen (GD01 bis 1 ha, GD02 < 0,30 ha, AG02 < 0,50 ha).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	m := lib.auflage_by_code[c].max_plot_area
	m != null
	area_exceeds(lib.area(parcel), m)
	v := {"rule_id": "O618-ELIG-017", "parcel_id": parcel.parcel_id, "message": sprintf("Schlaggröße %v ha unzulässig für Auflage %v", [lib.area(parcel), c])}
}

area_exceeds(a, m) if {
	m.strict
	a >= m.max_ha
}

area_exceeds(a, m) if {
	not m.strict
	a > m.max_ha
}

# O618-ELIG-019: Geförderte Flächen müssen in Österreich liegen.
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(parcel, ["oepul", "located_in_austria"], true) == false
	v := {"rule_id": "O618-ELIG-019", "parcel_id": parcel.parcel_id, "message": "Fläche liegt nicht in Österreich"}
}

# METADATA
# title: ÖPUL 2023 Naturschutz (18) – Sonderregelungen 2026 (AMA-Aktuell-Meldungen)
package oepul.o6_18.notices_2026

import data.oepul.o6_18.lib

p := lib.params

# O618-N26-001: Ab 12.08.2026 dürfen NAT-Flächen mit festgelegtem Nutzungstermin genutzt werden (1. oder 2. Nutzung);
# Projektbestätigung bleibt unverändert, Prämie wird gewährt.
early_use_release_active if {
	lib.year == 2026
}

released_use_allowed(parcel, date) if {
	early_use_release_active
	lib.is_nat(parcel)
	date >= p.drought_2026.naturschutz_use_release_date
}

premium_kept_despite_release if early_use_release_active

# O618-N26-002: Trockenheitsbedingte DIV-Ausnahmen (vorzeitige Nutzung mit OPUBB/OPBIO) umfassen keine NAT-Flächen.
violations contains v if {
	lib.year == 2026
	some parcel in lib.nat_parcels
	object.get(lib.ns(parcel), "drought_div_exception_used", false)
	v := {"rule_id": "O618-N26-002", "parcel_id": parcel.parcel_id, "message": "Trockenheitsbedingte DIV-Ausnahme gilt nicht für Naturschutzflächen – Bewirtschaftung nach Projektbestätigung"}
}

# O618-N26-003: Acker-Biodiversitätsflächen, die zusätzlich in NAT eingebracht sind: keine dritte Nutzung – nur nach Projektbestätigung.
violations contains v if {
	lib.year == 2026
	some parcel in lib.nat_parcels
	lib.has_code(parcel, "DIV")
	parcel.land_use == "arable"
	count(lib.cutting_dates(parcel)) + count(lib.grazing_periods(parcel)) >= 3
	not object.get(lib.pc(parcel), "third_use_permitted", false)
	v := {"rule_id": "O618-N26-003", "parcel_id": parcel.parcel_id, "message": "Dritte Nutzung 2026 auf NAT-Acker-Biodiversitätsfläche nicht von der Dürre-Erleichterung umfasst"}
}

# O618-N26-004: Dürre 2026 – Entfall der Ernteverpflichtung (85 %) ohne einzelbetriebliche Meldung in gelisteten Bezirken.
harvest_exemption_district if {
	lib.year == 2026
	some row in data.o6_18.drought_2026_harvest_exemption.districts
	row.federal_state == object.get(input, ["farm", "region", "federal_state"], null)
	district_match(row)
}

district_match(row) if row.all_districts

district_match(row) if row.district == object.get(input, ["farm", "region", "district"], null)

# O618-N26-005: Außerhalb der Gebietskulisse: einzelflächenbezogenes Ansuchen auf höhere Gewalt mit Nachweisen.
force_majeure_application_required contains parcel.parcel_id if {
	lib.year == 2026
	some parcel in lib.nat_parcels
	object.get(lib.ns(parcel), "drought_no_harvestable_crop", false)
	not harvest_exemption_district
}

# METADATA
# title: ÖPUL 2023 Naturschutz (18) – allgemeine Auflagen und Bewirtschaftungsauflagen laut Projektbestätigung
package oepul.o6_18.obligations

import data.oepul.o6_18.lib
import data.oepul.o6_18.notices_2026

p := lib.params

activities(parcel) := object.get(lib.ns(parcel), "activities", {})

activity(parcel, k) if object.get(activities(parcel), k, false) == true

is_grassland(parcel) if parcel.land_use == "grassland"

# Nutzungen im Jahr: Schnitte plus Weideperioden.
use_count(parcel) := count(lib.cutting_dates(parcel)) + count(lib.grazing_periods(parcel))

used_or_cared(parcel, y) if y in object.get(lib.ns(parcel), "use_or_care_years", [])

used_or_cared(parcel, y) if {
	y == lib.year
	use_count(parcel) > 0
}

# O618-OBL-001: Mindestens eine Nutzung/Pflege alle 2 Jahre.
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(lib.ns(parcel), "year_completed", false)
	not used_or_cared(parcel, lib.year)
	not used_or_cared(parcel, lib.year - 1)
	v := {"rule_id": "O618-OBL-001", "parcel_id": parcel.parcel_id, "message": "Keine Nutzung/Pflege innerhalb von 2 Jahren"}
}

# O618-OBL-002: Maximal 3 Nutzungen von Grünlandflächen pro Jahr.
violations contains v if {
	some parcel in lib.nat_parcels
	is_grassland(parcel)
	use_count(parcel) > p.general_obligations.max_grassland_uses_per_year
	v := {"rule_id": "O618-OBL-002", "parcel_id": parcel.parcel_id, "message": sprintf("%d Nutzungen auf Grünland (max. 3)", [use_count(parcel)])}
}

# O618-OBL-003: Keine maschinelle Entsteinung, Geländekorrekturen, Ablagerungen und Aufschüttungen.
violations contains v if {
	some parcel in lib.nat_parcels
	some k in ["mechanical_stone_removal", "terrain_correction", "deposits", "fill_up"]
	activity(parcel, k)
	v := {"rule_id": "O618-OBL-003", "parcel_id": parcel.parcel_id, "message": sprintf("Verbotene Maßnahme: %v", [k])}
}

# O618-OBL-004: Keine Neuentwässerung.
violations contains v if {
	some parcel in lib.nat_parcels
	activity(parcel, "new_drainage")
	v := {"rule_id": "O618-OBL-004", "parcel_id": parcel.parcel_id, "message": "Neuentwässerung ist verboten"}
}

# O618-OBL-005: Keine Lagerung von Siloballen.
violations contains v if {
	some parcel in lib.nat_parcels
	activity(parcel, "silage_bale_storage")
	v := {"rule_id": "O618-OBL-005", "parcel_id": parcel.parcel_id, "message": "Lagerung von Siloballen ist verboten"}
}

# O618-OBL-006: Keine Ein- oder Nachsaaten auf Grünland, außer Sanierung nach schriftlicher Genehmigung.
reseeding(parcel) := object.get(activities(parcel), "reseeding", {})

reseeding_exception(parcel) if {
	object.get(reseeding(parcel), "reason", null) in p.general_obligations.reseeding_exception_reasons
	object.get(reseeding(parcel), "written_approval", false)
}

violations contains v if {
	some parcel in lib.nat_parcels
	is_grassland(parcel)
	object.get(reseeding(parcel), "performed", false)
	not reseeding_exception(parcel)
	v := {"rule_id": "O618-OBL-006", "parcel_id": parcel.parcel_id, "message": "Ein-/Nachsaat auf Grünland ohne genehmigte Sanierungsausnahme"}
}

# O618-OBL-007: Keine zusätzliche Düngung auf Weideflächen (ausgenommen Mähweiden).
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(lib.ns(parcel), "grassland_type", null) in {"weide", "hutweide"}
	lib.fertilized(parcel)
	v := {"rule_id": "O618-OBL-007", "parcel_id": parcel.parcel_id, "message": "Zusätzliche Düngung auf Weidefläche (keine Mähweide)"}
}

# O618-OBL-008: Keine Ausbringung von Klärschlamm und Klärschlammkompost.
violations contains v if {
	some parcel in lib.nat_parcels
	some e in lib.fertilization_events(parcel)
	e.type in {"klaerschlamm", "klaerschlammkompost"}
	v := {"rule_id": "O618-OBL-008", "parcel_id": parcel.parcel_id, "message": "Ausbringung von Klärschlamm/Klärschlammkompost ist verboten"}
}

# O618-OBL-009: Weidetagebuch bei Auflagen mit verpflichtender Beweidung, tagaktuell.
requires_grazing(parcel) if {
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].requires_grazing
}

diary(parcel) := object.get(lib.ns(parcel), "grazing_diary", {})

violations contains v if {
	some parcel in lib.nat_parcels
	requires_grazing(parcel)
	not object.get(diary(parcel), "kept", false)
	v := {"rule_id": "O618-OBL-009", "parcel_id": parcel.parcel_id, "message": "Weidetagebuch fehlt trotz Auflage mit verpflichtender Beweidung"}
}

violations contains v if {
	some parcel in lib.nat_parcels
	requires_grazing(parcel)
	object.get(diary(parcel), "kept", false)
	not object.get(diary(parcel), "daily_current", false)
	v := {"rule_id": "O618-OBL-009", "parcel_id": parcel.parcel_id, "message": "Weidetagebuch nicht tagaktuell geführt"}
}

# O618-OBL-013: Zusammengefasste Weideaufzeichnungen nur bei gleicher Bewirtschaftung und erkennbarer Einheit.
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(diary(parcel), "combined_with_other_plots", false)
	not object.get(diary(parcel), "same_management_and_visible_unit", false)
	v := {"rule_id": "O618-OBL-013", "parcel_id": parcel.parcel_id, "message": "Zusammengefasste Weideaufzeichnung ohne gleiche Bewirtschaftung/erkennbare Einheit"}
}

# O618-OBL-010: Abänderung der Bewirtschaftung nur nach Rücksprache und schriftlicher Abänderung der Projektbestätigung.
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(lib.pc(parcel), "management_deviates", false)
	not object.get(lib.pc(parcel), "written_amendment", false)
	v := {"rule_id": "O618-OBL-010", "parcel_id": parcel.parcel_id, "message": "Abweichende Bewirtschaftung ohne schriftliche Abänderung der Projektbestätigung"}
}

# O618-N26-001 (Freigabe 2026): ab 12.08.2026 Nutzung trotz späterem Nutzungstermin zulässig.
effective_date(d) := lib.min2(d, p.drought_2026.naturschutz_use_release_date) if lib.year == 2026

effective_date(d) := d if lib.year != 2026

# O618-OBL-011A: Früheste Mahd laut Projektbestätigung (GL-Auflagen, NM05).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].earliest_mowing_date_parameter
	earliest := object.get(lib.pc(parcel), "earliest_mowing_date", null)
	earliest != null
	some d in lib.cutting_dates(parcel)
	d < effective_date(earliest)
	v := {"rule_id": "O618-OBL-011A", "parcel_id": parcel.parcel_id, "message": sprintf("Mahd am %v vor frühestem Mahdtermin %v (Auflage %v)", [d, effective_date(earliest), c])}
}

# O618-OBL-011B: Anzahl der Mahden gemäß GA-Auflage (3/2/1 x Mahd und Abtransport pro Jahr).
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(lib.ns(parcel), "year_completed", false)
	some c in lib.auflagen_of(parcel)
	n := lib.auflage_by_code[c].required_mowings_per_year
	n != null
	count(lib.cutting_dates(parcel)) != n
	v := {"rule_id": "O618-OBL-011B", "parcel_id": parcel.parcel_id, "message": sprintf("Auflage %v verlangt %d Mahd(en), erfolgt: %d", [c, n, count(lib.cutting_dates(parcel))])}
}

fert_rule(parcel) := {r |
	some c in lib.auflagen_of(parcel)
	r := lib.auflage_by_code[c].fertilization_rule
	r != null
}

# O618-OBL-011C: Düngeverbot bzw. Verbot zusätzlicher Düngung.
violations contains v if {
	some parcel in lib.nat_parcels
	some r in fert_rule(parcel)
	r in {"ban", "additional_ban"}
	lib.fertilized(parcel)
	v := {"rule_id": "O618-OBL-011C", "parcel_id": parcel.parcel_id, "message": "Düngung trotz Düngeverbot laut Projektbestätigung"}
}

# O618-OBL-011D: Düngung nur mit Festmist.
violations contains v if {
	some parcel in lib.nat_parcels
	some r in fert_rule(parcel)
	r in {"solid_manure_only", "solid_manure_every_second_year", "solid_manure_two_years_from_sept"}
	some e in lib.fertilization_events(parcel)
	e.type != "festmist"
	v := {"rule_id": "O618-OBL-011D", "parcel_id": parcel.parcel_id, "message": sprintf("Düngung mit %v, erlaubt ist nur Festmist", [e.type])}
}

violations contains v if {
	some parcel in lib.nat_parcels
	some r in fert_rule(parcel)
	r in {"solid_manure_only", "solid_manure_every_second_year", "solid_manure_two_years_from_sept", "farm_manure_from_sept", "farm_manure_only"}
	lib.mineral_fertilized(parcel)
	v := {"rule_id": "O618-OBL-011D", "parcel_id": parcel.parcel_id, "message": "Mineralische Düngung bei Festmist-/Wirtschaftsdüngerauflage unzulässig"}
}

# O618-OBL-011E: Düngung mit Wirtschaftsdüngern frühestens ab 01.09. (GI22-GI25, BB07).
violations contains v if {
	some parcel in lib.nat_parcels
	some r in fert_rule(parcel)
	r in {"farm_manure_from_sept", "solid_manure_two_years_from_sept"}
	some e in lib.fertilization_events(parcel)
	substring(e.date, 5, 5) < "09-01"
	v := {"rule_id": "O618-OBL-011E", "parcel_id": parcel.parcel_id, "message": sprintf("Düngung am %v vor dem 01.09.", [e.date])}
}

# O618-OBL-011S: Düngung nur in den festgelegten Jahren (jedes 2. Jahr bzw. Jahre $1/$2).
violations contains v if {
	some parcel in lib.nat_parcels
	some r in fert_rule(parcel)
	r in {"solid_manure_every_second_year", "solid_manure_two_years_from_sept", "every_second_year"}
	allowed := object.get(lib.pc(parcel), "fertilization_allowed_years", null)
	allowed != null
	lib.fertilized(parcel)
	not lib.year in allowed
	v := {"rule_id": "O618-OBL-011S", "parcel_id": parcel.parcel_id, "message": sprintf("Düngung im Jahr %d laut Projektbestätigung nicht erlaubt", [lib.year])}
}

# O618-OBL-011F: Pflanzenschutzmittel-/Pestizidverbot (TC01: ausgenommen Mittel gemäß EU-Bio-Verordnung).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].psm_ban
	object.get(parcel, ["operations", "psm_used"], false)
	v := {"rule_id": "O618-OBL-011F", "parcel_id": parcel.parcel_id, "message": sprintf("Pflanzenschutzmitteleinsatz trotz Auflage %v", [c])}
}

violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].psm_ban_except_eu_organic
	object.get(parcel, ["operations", "psm_used"], false)
	not object.get(lib.ns(parcel), "psm_only_eu_organic_approved", false)
	v := {"rule_id": "O618-OBL-011F", "parcel_id": parcel.parcel_id, "message": sprintf("Pestizideinsatz (nicht EU-Bio-konform) trotz Auflage %v", [c])}
}

# O618-OBL-011G: Maisverzicht (TD01).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].maize_ban
	object.get(parcel, ["crop", "crop_category"], null) == "maize"
	v := {"rule_id": "O618-OBL-011G", "parcel_id": parcel.parcel_id, "message": "Maisanbau trotz Maisverzicht (TD01)"}
}

# O618-OBL-011H: Beweidungsverbot (NW09).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].grazing_ban
	lib.is_grazed(parcel)
	v := {"rule_id": "O618-OBL-011H", "parcel_id": parcel.parcel_id, "message": "Beweidung trotz Beweidungsverbot (NW09)"}
}

# O618-OBL-011I: Keine Beweidung vor dem 1. Schnitt (GB01, NW10).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].grazing_before_first_cut_ban
	some g in lib.grazing_periods(parcel)
	grazed_before_first_cut(parcel, g)
	v := {"rule_id": "O618-OBL-011I", "parcel_id": parcel.parcel_id, "message": sprintf("Beweidung ab %v vor dem 1. Schnitt (Auflage %v)", [g.start, c])}
}

grazed_before_first_cut(parcel, g) if g.start < lib.first_cut(parcel)

grazed_before_first_cut(parcel, _) if count(lib.cutting_dates(parcel)) == 0

# O618-OBL-011J: Keine Beweidung nach dem letzten Schnitt (NW11).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].grazing_after_last_cut_ban
	some g in lib.grazing_periods(parcel)
	g.end > lib.last_cut(parcel)
	v := {"rule_id": "O618-OBL-011J", "parcel_id": parcel.parcel_id, "message": "Beweidung nach dem letzten Schnitt (NW11)"}
}

# O618-OBL-011K: Viehbesatz bei Weideauflagen (WA01 max. 1 RGVE/ha und Jahr, WA03 max. 0,5 RGVE/ha und Jahr).
period_days(g) := lib.days_between(g.start, g.end) + 1

rgve_day_terms(parcel) := [t |
	some g in lib.grazing_periods(parcel)
	some a in object.get(g, "animals", [])
	t := (a.count * key_rgve(a.annex_a_key)) * period_days(g)
]

rgve_days(parcel) := sum(rgve_day_terms(parcel))

key_rgve(k) := r.rgve if {
	some r in data.o6_18.annex_a_gve_key.rows
	r.key == k
	r.rgve != null
}

rgve_per_ha_year(parcel) := (rgve_days(parcel) / 365) / lib.area(parcel) if lib.area(parcel) > 0

violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	limit := lib.auflage_by_code[c].max_rgve_per_ha_year
	limit != null
	rgve_per_ha_year(parcel) > limit
	v := {"rule_id": "O618-OBL-011K", "parcel_id": parcel.parcel_id, "message": sprintf("Viehbesatz %.2f RGVE/ha und Jahr über Grenze %v (Auflage %v)", [rgve_per_ha_year(parcel), limit, c])}
}

# NW05/NW06: maximaler GVE-Besatz laut Projektbestätigung.
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["NW06"])
	limit := object.get(lib.pc(parcel), "max_gve_per_ha", null)
	limit != null
	rgve_per_ha_year(parcel) > limit
	v := {"rule_id": "O618-OBL-011K", "parcel_id": parcel.parcel_id, "message": "Viehbesatz über Maximalbesatz laut Projektbestätigung (NW06)"}
}

# O618-OBL-011L: Zeitfenster zwischen erster und zweiter Nutzung mindestens 9 Wochen (GN03).
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_auflage(parcel, "GN03")
	count(lib.cutting_dates(parcel)) >= 2
	lib.days_between(lib.sorted_cuts(parcel)[0], lib.sorted_cuts(parcel)[1]) < 63
	v := {"rule_id": "O618-OBL-011L", "parcel_id": parcel.parcel_id, "message": "Weniger als 9 Wochen zwischen erster und zweiter Nutzung (GN03)"}
}

# O618-OBL-011M: 2. Nutzung erst ab Termin laut Projektbestätigung (GN01, GN02 ab 01.09.).
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["GN01", "GN02"])
	d2 := object.get(lib.pc(parcel), "second_use_earliest_date", null)
	d2 != null
	count(lib.cutting_dates(parcel)) >= 2
	lib.sorted_cuts(parcel)[1] < effective_date(d2)
	v := {"rule_id": "O618-OBL-011M", "parcel_id": parcel.parcel_id, "message": sprintf("2. Nutzung vor %v", [effective_date(d2)])}
}

# O618-OBL-011N: Frühe erste Mahd vor Termin und weitere Mahd (GK02, BG01).
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["GK02", "BG01"])
	before := object.get(lib.pc(parcel), "first_mowing_before_date", null)
	before != null
	count(lib.cutting_dates(parcel)) > 0
	lib.first_cut(parcel) >= before
	v := {"rule_id": "O618-OBL-011N", "parcel_id": parcel.parcel_id, "message": sprintf("1. Mahd nicht vor %v", [before])}
}

violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["GK02", "BG01"])
	object.get(lib.ns(parcel), "year_completed", false)
	count(lib.cutting_dates(parcel)) < 2
	v := {"rule_id": "O618-OBL-011N", "parcel_id": parcel.parcel_id, "message": "Keine weitere Mahd nach früher erster Mahd"}
}

# O618-OBL-011O: Bewässerungsverbot (NA06, NV07).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].irrigation_ban
	object.get(lib.ns(parcel), "irrigation_used", false)
	v := {"rule_id": "O618-OBL-011O", "parcel_id": parcel.parcel_id, "message": sprintf("Bewässerung trotz Auflage %v", [c])}
}

# O618-OBL-011P: Silageverbot (NA22, GM01).
violations contains v if {
	some parcel in lib.nat_parcels
	some c in lib.auflagen_of(parcel)
	lib.auflage_by_code[c].silage_ban
	object.get(lib.ns(parcel), "silage_produced", false)
	v := {"rule_id": "O618-OBL-011P", "parcel_id": parcel.parcel_id, "message": sprintf("Silageproduktion trotz Auflage %v", [c])}
}

# O618-OBL-011Q: Beweidungszeitraum laut Projektbestätigung (WA01/WA03/BA03/BA04: frühestens ab $1, längstens bis $2).
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["WA01", "WA03", "BA03", "BA04", "NW17"])
	start := object.get(lib.pc(parcel), "grazing_window_start", null)
	start != null
	some g in lib.grazing_periods(parcel)
	g.start < start
	v := {"rule_id": "O618-OBL-011Q", "parcel_id": parcel.parcel_id, "message": sprintf("Beweidung ab %v vor erlaubtem Beginn %v", [g.start, start])}
}

violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["WA01", "WA03", "BA03", "BA04", "NW17"])
	end := object.get(lib.pc(parcel), "grazing_window_end", null)
	end != null
	some g in lib.grazing_periods(parcel)
	g.end > end
	v := {"rule_id": "O618-OBL-011Q", "parcel_id": parcel.parcel_id, "message": sprintf("Beweidung bis %v nach erlaubtem Ende %v", [g.end, end])}
}

# O618-OBL-011R: Mähweide-Nutzungsmuster (GA15/GA17 max. 2 x Weide, mind. 1 x Mahd, max. 3 Nutzungen; GA16/GA18 1 x Weide und 1 x Mahd).
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(lib.ns(parcel), "year_completed", false)
	some c in lib.auflagen_of(parcel)
	pat := lib.auflage_by_code[c].maehweide_pattern
	pat != null
	not maehweide_ok(parcel, pat)
	v := {"rule_id": "O618-OBL-011R", "parcel_id": parcel.parcel_id, "message": sprintf("Nutzungsmuster der Mähweide-Auflage %v nicht eingehalten", [c])}
}

maehweide_ok(parcel, pat) if {
	pat.max_grazings
	count(lib.grazing_periods(parcel)) <= pat.max_grazings
	count(lib.cutting_dates(parcel)) >= pat.min_mowings
	use_count(parcel) <= pat.max_uses
}

maehweide_ok(parcel, pat) if {
	pat.grazings
	count(lib.grazing_periods(parcel)) == pat.grazings
	count(lib.cutting_dates(parcel)) == pat.mowings
}

# O618-OBL-011T: Befahren der Mähwiese/Mähweide bis zum 1. Schnitt verboten (GB01).
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["GB01"])
	object.get(lib.ns(parcel), "driven_on_before_first_cut", false)
	v := {"rule_id": "O618-OBL-011T", "parcel_id": parcel.parcel_id, "message": "Befahren vor dem 1. Schnitt (GB01)"}
}

# O618-OBL-011U: Verzicht auf Erneuerung/Wartung von Drainagen (GC01-GC03) und Grabenfräsen (GC04).
violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["GC01", "GC02", "GC03"])
	activity(parcel, "drainage_maintenance")
	v := {"rule_id": "O618-OBL-011U", "parcel_id": parcel.parcel_id, "message": "Erneuerung oder Wartung von Drainagen verboten"}
}

violations contains v if {
	some parcel in lib.nat_parcels
	lib.has_any_auflage(parcel, ["GC04"])
	activity(parcel, "trench_milling")
	v := {"rule_id": "O618-OBL-011U", "parcel_id": parcel.parcel_id, "message": "Grabenräumung mit Grabenfräse verboten (GC04)"}
}

# O618-OBL-012: Nachweide auf Bergmahd-Naturschutzflächen nur, wenn als Auflage ausgewiesen (auch nicht ab 16.08.).
violations contains v if {
	some parcel in lib.nat_parcels
	object.get(lib.ns(parcel), "is_bergmahd", false)
	count(lib.cutting_dates(parcel)) > 0
	some g in lib.grazing_periods(parcel)
	g.start > lib.last_cut(parcel)
	not lib.has_any_auflage(parcel, p.nachweide_allowing_codes)
	v := {"rule_id": "O618-OBL-012", "parcel_id": parcel.parcel_id, "message": "Nachweide auf Bergmahd-Naturschutzfläche ohne entsprechende Auflage"}
}

# O618-OBL-014: Ernteverpflichtung (85 %) auf bewirtschafteten NAT-Ackerflächen (Kapitel A); 2026 Dürre-Ausnahme.
chapter_a_arable(parcel) if {
	some c in lib.auflagen_of(parcel)
	lib.chapter_of(c) == "A"
}

violations contains v if {
	some parcel in lib.nat_parcels
	parcel.land_use == "arable"
	chapter_a_arable(parcel)
	share := object.get(lib.ns(parcel), "harvest_share", null)
	share != null
	share < 0.85
	not drought_harvest_exempt(parcel)
	v := {"rule_id": "O618-OBL-014", "parcel_id": parcel.parcel_id, "message": sprintf("Ernte nur auf %v des Schlages (mind. 85 %%)", [share])}
}

drought_harvest_exempt(parcel) if {
	lib.year == 2026
	object.get(lib.ns(parcel), "drought_no_harvestable_crop", false)
	notices_2026.harvest_exemption_district
}

# O618-OBL-015: NAT-Grünbrachen sind von den Mindestbewirtschaftungskriterien ausgenommen.
minimum_criteria_exempt contains parcel.parcel_id if {
	some parcel in lib.nat_parcels
	object.get(parcel, ["oepul", "schlagnutzung"], null) == "Grünbrache"
}

# METADATA
# title: ÖPUL 2023 Naturschutz (18) – Prämienberechnung
package oepul.o6_18.premium

import data.oepul.o6_18.eligibility
import data.oepul.o6_18.lib

p := lib.params

y := lib.year

# O618-PREM-012: Die Prämiensätze des Anhang I gelten ab 01.01.2024; für 2023 enthalten die Quellen keine Sätze.
rates_available if y >= 2024

# O618-PREM-001: Schlagprämie ergibt sich aus der Summe der Teilprämien der Auflagen laut Projektbestätigung (Anhang I).
base_rate(parcel) := sum([r |
	some c in lib.auflagen_of(parcel)
	lib.valid_in_year(c, y)
	r := lib.rate_for(c, y)
])

# O618-PREM-002: Prämienzuschläge (SA01 Ackerzahl > 50; GM01 bei Heuwirtschaft; HG01/HG02 bei >= 50 % Schutzgutflächen).
surcharge_applies("ackerzahl_over_50", parcel) if object.get(lib.ns(parcel), "ackerzahl", 0) > 50

surcharge_applies("participation_heuwirtschaft", _) if lib.participates("3")

surcharge_applies("schutzgut_layer_share_at_least_50_percent", parcel) if object.get(lib.ns(parcel), "schutzgut_layer_share", 0) >= 0.5

surcharge_rate(parcel) := sum([s.eur_ha |
	some c in lib.auflagen_of(parcel)
	lib.valid_in_year(c, y)
	some s in lib.auflage_by_code[c].surcharges
	surcharge_applies(s.condition, parcel)
])

rate_per_ha(parcel) := base_rate(parcel) + surcharge_rate(parcel)

# O618-PREM-003: GLÖZ-4-Pufferstreifen und (bis 2024) GLÖZ-8-Stilllegungen sind auf dem Flächenteil nicht förderbar.
gloez8_area(parcel) := object.get(parcel, ["oepul", "gloez8_fallow_area_ha"], 0) if y <= p.gloez8_non_eligible_until_year

gloez8_area(_) := 0 if y > p.gloez8_non_eligible_until_year

eligible_area(parcel) := lib.max2(0, (lib.area(parcel) - object.get(parcel, ["oepul", "gloez4_buffer_area_ha"], 0)) - gloez8_area(parcel))

# O618-PREM-005/006/007/016: Schläge ohne Prämie.
reason_applies("code_without_premium", parcel) if {
	some c in p.no_premium_codes
	c != "NPF"
	lib.has_code(parcel, c)
}

reason_applies("npf_gloez8", parcel) if {
	lib.has_code(parcel, "NPF")
	y <= p.npf_code_until_year
}

reason_applies("national_park_no_area_premium", parcel) if {
	object.get(parcel, ["oepul", "national_park"], null) in p.national_parks_without_area_premiums
}

reason_applies("national_park_relevant_requirements", parcel) if {
	np := object.get(parcel, ["oepul", "national_park"], null)
	np != null
	not np in p.national_parks_without_area_premiums
	object.get(parcel, ["oepul", "national_park_relevant_requirements"], false)
}

reason_applies("no_reference_area", parcel) if {
	parcel.parcel_id in eligibility.no_payment_parcels
}

reason_applies("transferred_without_continuation", parcel) if {
	object.get(parcel, ["oepul", "transferred_during_year"], false)
	not object.get(parcel, ["oepul", "successor_continues_until_year_end"], false)
}

reason_applies("no_project_confirmation", parcel) if {
	not object.get(lib.pc(parcel), "present", false)
}

reason_codes := [
	"code_without_premium", "npf_gloez8", "national_park_no_area_premium",
	"national_park_relevant_requirements", "no_reference_area",
	"transferred_without_continuation", "no_project_confirmation",
]

reasons(parcel) := {r | some r in reason_codes; reason_applies(r, parcel)}

paid_parcels := [parcel |
	some parcel in lib.nat_parcels
	count(reasons(parcel)) == 0
]

# O618-PREM-004: Ackerstilllegungen max. 25 % der Ackerfläche des Betriebes, jedenfalls 2 ha förderfähig.
is_set_aside(parcel) if lib.has_any_auflage(parcel, p.set_aside_cap.auflage_codes)

set_aside_area := sum([eligible_area(parcel) | some parcel in paid_parcels; is_set_aside(parcel)])

set_aside_cap_ha := lib.max2(p.set_aside_cap.share_of_arable_area * object.get(input, ["land", "arable_area_ha"], 0), p.set_aside_cap.minimum_ha)

set_aside_factor := 1 if set_aside_area <= set_aside_cap_ha

set_aside_factor := set_aside_cap_ha / set_aside_area if set_aside_area > set_aside_cap_ha

area_factor(parcel) := set_aside_factor if is_set_aside(parcel)

area_factor(parcel) := 1 if not is_set_aside(parcel)

# O618-PREM-013: Prämienfähigkeit von Flächenzugängen ab 2026 max. 50 % auf Basis 2025, jedenfalls + 5 ha.
nat_area_total := sum([lib.area(parcel) | some parcel in lib.nat_parcels])

access_limit_ha := base + lib.max2(p.area_increase.max_increase_share * base, p.area_increase.always_allowed_ha) if {
	y > 2025
	base := object.get(lib.nat, "area_2025_ha", null)
	base != null
}

eligible_nat_area_total := lib.min2(nat_area_total, access_limit_ha) + object.get(lib.nat, "previously_committed_added_area_ha", 0)

access_factor := 1 if not access_limit_ha

access_factor := 1 if {
	access_limit_ha
	nat_area_total <= eligible_nat_area_total
}

access_factor := eligible_nat_area_total / nat_area_total if {
	access_limit_ha
	nat_area_total > eligible_nat_area_total
}

# O618-PREM-009: Modulation nach Gesamtfläche des Betriebes.
farm_area := object.get(input, ["land", "total_area_ha"], 0)

band_amount(b) := (lib.min2(farm_area, b.to_ha) - b.from_ha) * b.factor if {
	b.to_ha != null
	farm_area > b.from_ha
}

band_amount(b) := (farm_area - b.from_ha) * b.factor if {
	b.to_ha == null
	farm_area > b.from_ha
}

band_amount(b) := 0 if farm_area <= b.from_ha

modulation_factor := 1 if farm_area <= 0

modulation_factor := sum([band_amount(b) | some b in p.modulation_bands]) / farm_area if farm_area > 0

# O618-PREM-008: Obergrenze der flächenbezogenen Zahlungen je Schlag (NAT/EBW: 1.300 €/ha 2023, 1.500 €/ha ab 2024).
cap_per_ha := lib.year_value(p.payment_caps_eur_per_ha, y)

other_payments(parcel) := object.get(parcel, ["oepul", "other_area_payments_eur_per_ha"], 0)

capped_rate(parcel) := lib.max2(0, lib.min2(rate_per_ha(parcel) * modulation_factor, cap_per_ha - other_payments(parcel)))

parcel_premium[parcel.parcel_id] := round((((eligible_area(parcel) * area_factor(parcel)) * access_factor) * capped_rate(parcel)) * 100) / 100 if {
	rates_available
	some parcel in paid_parcels
}

parcel_premium[parcel.parcel_id] := 0 if {
	some parcel in lib.nat_parcels
	count(reasons(parcel)) > 0
}

no_premium_reasons[parcel.parcel_id] := reasons(parcel) if {
	some parcel in lib.nat_parcels
	count(reasons(parcel)) > 0
}

# O618-PREM-010: Zuschlag Regionaler Naturschutzplan je Betrieb und Jahr (250 € 2023, 270 € ab 2024), bei NAT+EBW nur einmal.
regional_plan_premium := lib.year_value(p.regional_plan.premium_eur_per_farm, y) * modulation_factor if eligibility.regional_plan_eligible

regional_plan_premium := 0 if not eligibility.regional_plan_eligible

regional_plan_already_granted_via_ebw if object.get(object.get(lib.nat, "regional_plan", {}), "granted_via_ebw", false)

regional_plan_payable := 0 if regional_plan_already_granted_via_ebw

regional_plan_payable := regional_plan_premium if not regional_plan_already_granted_via_ebw

total_premium := round((sum([v | some v in parcel_premium]) + regional_plan_payable) * 100) / 100 if rates_available

# O618-PREM-011: Auszahlungsbeträge bis 50 € können unterbleiben.
payment_may_be_withheld if total_premium <= p.min_payout_eur

# O618-PREM-015: Teilzahlung max. 75 % nach Verwaltungskontrolle; Auszahlung bis 30.06. des Folgejahres.
max_advance_payment := total_premium * p.advance_payment_max_share

payout_deadline := sprintf("%d-06-30", [y + 1])

findings contains f if {
	not rates_available
	f := {"rule_id": "O618-PREM-012", "message": "Für das Antragsjahr 2023 enthalten die Quellen keine Anhang-I-Prämiensätze (gelten ab 01.01.2024)"}
}

findings contains f if {
	set_aside_area > set_aside_cap_ha
	f := {"rule_id": "O618-PREM-004", "message": sprintf("Ackerstilllegungen %.2f ha über förderfähiger Obergrenze %.2f ha", [set_aside_area, set_aside_cap_ha])}
}

findings contains f if {
	access_factor < 1
	f := {"rule_id": "O618-PREM-013", "message": "Flächenzugang über prämienfähiger Grenze (50 % auf Basis 2025, mind. 5 ha)"}
}

findings contains f if {
	some parcel in paid_parcels
	rate_per_ha(parcel) * modulation_factor > cap_per_ha - other_payments(parcel)
	f := {"rule_id": "O618-PREM-008", "message": sprintf("Schlag %v: Prämienobergrenze %v €/ha greift", [parcel.parcel_id, cap_per_ha])}
